// Control UI view renders debug screen content.
import { html, nothing } from "lit";
import { guard } from "lit/directives/guard.js";
import { repeat } from "lit/directives/repeat.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import type { EventLogEntry } from "../../api/event-log.ts";
import { isNativeEmbedHost } from "../../app/native-web-chrome.ts";
import { highlightJsonHtml } from "../../components/markdown-code-blocks.ts";
import {
  renderSettingsEmpty,
  renderSettingsPage,
  renderSettingsRow,
  renderSettingsSection,
  renderSettingsStatus,
} from "../../components/settings-ui.ts";
import { t } from "../../i18n/index.ts";
import { formatTimeMs } from "../../lib/format.ts";
import type {
  CommandLaneDynamicSummary,
  CommandLaneSnapshot,
} from "../../lib/gateway-diagnostics.ts";
import { formatEventPayload } from "../../lib/presenter.ts";
import { DEBUG_OVERLAY_SHORTCUT_LABEL } from "./debug-overlay-contract.ts";
import { renderCommandLaneRows } from "./lane-table.ts";

type DebugProps = {
  connected: boolean;
  offlineStable: boolean;
  loading: boolean;
  status: Record<string, unknown> | null;
  health: Record<string, unknown> | null;
  models: unknown[];
  heartbeat: unknown;
  lanes: CommandLaneSnapshot[];
  dynamic: CommandLaneDynamicSummary | null;
  diagnosticsError: string | null;
  eventLog: readonly EventLogEntry[];
  methods: string[];
  callMethod: string;
  callParams: string;
  callResult: string | null;
  callError: string | null;
  onCallMethodChange: (next: string) => void;
  onCallParamsChange: (next: string) => void;
  onRefresh: () => void;
  onOpenOverlay: () => void;
  onCall: () => void;
};

function renderJsonRow(title: unknown, value: unknown) {
  return renderSettingsRow({
    title,
    stacked: true,
    control: html`<pre class="code-block">
${guard([value], () => unsafeHTML(highlightJsonHtml(JSON.stringify(value ?? {}, null, 2))))}</pre>`,
  });
}

function renderSecurityRow(props: DebugProps) {
  const securityAudit =
    props.status && typeof props.status === "object"
      ? (props.status as { securityAudit?: { summary?: Record<string, number> } }).securityAudit
      : null;
  const securitySummary = securityAudit?.summary ?? null;
  if (!securitySummary) {
    return nothing;
  }
  const critical = securitySummary.critical ?? 0;
  const warn = securitySummary.warn ?? 0;
  const info = securitySummary.info ?? 0;
  const securityKind = critical > 0 ? "danger" : warn > 0 ? "warn" : "ok";
  const securityLabel =
    critical > 0
      ? t("debug.security.critical", { count: String(critical) })
      : warn > 0
        ? t("debug.security.warnings", { count: String(warn) })
        : t("debug.security.noCriticalIssues");
  const infoSuffix = info > 0 ? ` · ${t("debug.security.info", { count: String(info) })}` : "";
  return renderSettingsRow({
    title: t("debug.security.audit"),
    description: html`
      ${t("debug.security.runPrefix")}
      <span class="mono">openclaw security audit --deep</span>
      ${t("debug.security.runSuffix")}
    `,
    control: renderSettingsStatus({ kind: securityKind, label: `${securityLabel}${infoSuffix}` }),
  });
}

function renderDiagnosticsError(error: string | null) {
  if (!error) {
    return nothing;
  }
  return html`
    <div class="settings-row" role="alert">
      <div class="settings-row__text">
        <span class="settings-row__title">
          ${renderSettingsStatus({ kind: "danger", label: t("common.failed") })}
        </span>
        <span class="settings-row__desc">${error}</span>
      </div>
    </div>
  `;
}

function renderSnapshotOffline(props: DebugProps) {
  if (props.connected || !props.offlineStable) {
    return nothing;
  }
  return renderSettingsRow({
    title: renderSettingsStatus({ kind: "muted", label: t("common.offline") }),
    description: t("debug.offlineSnapshots"),
  });
}

function renderEventRow(evt: EventLogEntry) {
  return renderSettingsRow({
    title: evt.event,
    description: formatTimeMs(evt.ts, undefined, ""),
    stacked: true,
    control: html`<pre class="code-block">
${guard([evt.payload], () => unsafeHTML(highlightJsonHtml(formatEventPayload(evt.payload))))}</pre>`,
  });
}

export function renderDebug(props: DebugProps) {
  const refreshPending = props.connected && props.loading;
  const snapshotsSection = renderSettingsSection(
    {
      title: t("debug.snapshotsTitle"),
      description: t("debug.snapshotsSubtitle"),
      actions: html`
        <button
          class="btn"
          ?disabled=${!props.connected || props.loading}
          @click=${props.onRefresh}
        >
          ${refreshPending ? t("common.refreshing") : t("common.refresh")}
        </button>
      `,
    },
    html`
      ${renderSnapshotOffline(props)} ${renderDiagnosticsError(props.diagnosticsError)}
      ${renderSecurityRow(props)} ${renderJsonRow(t("debug.status"), props.status)}
      ${renderJsonRow(t("debug.health"), props.health)}
      ${renderJsonRow(t("debug.lastHeartbeat"), props.heartbeat)}
    `,
  );

  const lanesSection = renderSettingsSection(
    {
      title: t("debug.lanes.title"),
      description: t("debug.lanes.subtitle"),
      actions: html`
        <button class="btn" @click=${props.onOpenOverlay}>
          ${
            isNativeEmbedHost()
              ? t("debug.overlay.open")
              : t("debug.overlay.openWithShortcut", { shortcut: DEBUG_OVERLAY_SHORTCUT_LABEL })
          }
        </button>
      `,
    },
    html`
      <div class="data-table-container command-lanes-table-wrap">
        <table class="data-table command-lanes-table settings-table--stacked" role="table">
          <thead>
            <tr>
              <th scope="col">${t("debug.lanes.lane")}</th>
              <th scope="col">${t("debug.lanes.active")}</th>
              <th scope="col">${t("debug.lanes.queued")}</th>
              <th scope="col">${t("debug.lanes.group")}</th>
              <th scope="col">${t("debug.lanes.blocked")}</th>
            </tr>
          </thead>
          <tbody>
            ${renderCommandLaneRows({ lanes: props.lanes, dynamic: props.dynamic })}
          </tbody>
        </table>
      </div>
    `,
  );

  const rpcSection = renderSettingsSection(
    { title: t("debug.manualRpcTitle"), description: t("debug.manualRpcSubtitle") },
    html`
      ${renderSettingsRow({
        title: t("debug.method"),
        control: html`
          <select
            class="settings-select"
            aria-label=${t("debug.method")}
            .value=${props.callMethod}
            @change=${(e: Event) => props.onCallMethodChange((e.target as HTMLSelectElement).value)}
          >
            ${
              !props.callMethod
                ? html` <option value="" disabled>${t("debug.selectMethod")}</option> `
                : nothing
            }
            ${props.methods.map((m) => html`<option value=${m}>${m}</option>`)}
          </select>
        `,
      })}
      ${renderSettingsRow({
        title: t("debug.paramsJson"),
        stacked: true,
        control: html`
          <textarea
            class="settings-input"
            aria-label=${t("debug.paramsJson")}
            .value=${props.callParams}
            @input=${(e: Event) =>
              props.onCallParamsChange((e.target as HTMLTextAreaElement).value)}
            rows="6"
          ></textarea>
        `,
      })}
      ${renderSettingsRow({
        title: t("common.call"),
        control: html`
          <button class="btn primary" @click=${props.onCall}>${t("common.call")}</button>
        `,
      })}
      ${
        props.callError
          ? html`
              <div class="settings-row settings-row--stacked">
                ${renderSettingsStatus({ kind: "danger", label: t("debug.callFailed") })}
                <pre class="code-block">${props.callError}</pre>
              </div>
            `
          : nothing
      }
      ${
        props.callResult
          ? html`
              <div class="settings-row settings-row--stacked">
                ${renderSettingsStatus({ kind: "ok", label: t("common.ok") })}
                <pre class="code-block">
${guard([props.callResult], () => unsafeHTML(highlightJsonHtml(props.callResult!)))}</pre>
              </div>
            `
          : nothing
      }
    `,
  );

  const modelsSection = renderSettingsSection(
    { title: t("debug.modelsTitle"), description: t("debug.modelsSubtitle") },
    html`
      <div class="settings-row settings-row--stacked">
        <pre class="code-block">
${guard([props.models], () => unsafeHTML(highlightJsonHtml(JSON.stringify(props.models ?? [], null, 2))))}</pre>
      </div>
    `,
  );

  const eventLogSection = renderSettingsSection(
    { title: t("debug.eventLogTitle"), description: t("debug.eventLogSubtitle") },
    props.eventLog.length === 0
      ? renderSettingsEmpty(t("debug.noEvents"))
      : // Entries retain their identity as the log prepends and evicts. Keep their
        // highlighted DOM and selection attached to the event, not its list index.
        repeat(props.eventLog, (evt) => evt, renderEventRow),
  );

  return renderSettingsPage(
    html`${snapshotsSection} ${lanesSection} ${rpcSection} ${modelsSection} ${eventLogSection}`,
    { wide: true },
  );
}
